function rotateGrid(sourceMatrix) {
  const gridDimension = sourceMatrix.length;

  // Utilize Array.from with nested map operations for a functional transformation
  // instead of imperative nested loops.
  // Each new row is generated by mapping over the column indices.
  return Array.from({ length: gridDimension }, (_, newRowIndex) =>
    Array.from({ length: gridDimension }, (_, newColumnIndex) =>
      // The value for the new cell [newRowIndex][newColumnIndex]
      // comes from the original sourceMatrix at:
      // old_row = (gridDimension - 1) - newColumnIndex
      // old_col = newRowIndex
      sourceMatrix[gridDimension - 1 - newColumnIndex][newRowIndex]
    )
  );
}

// Use 'node:fs' for explicit Node.js built-in module import.
const rawInputContent = require('node:fs').readFileSync('/dev/stdin', 'utf8');

// Process input using functional array methods.
// Trim whitespace, split into lines, then map each line to an array of characters.
let currentGridState = rawInputContent.trim().split('\n').map(lineSegment => lineSegment.split(''));

// Define a separate utility for consistent matrix formatting.
const renderMatrixAsString = (matrixToRender) =>
  matrixToRender.map(rowSegment => rowSegment.join('')).join('\n');

// Apply rotations and output results, updating the grid state each time.
// The assignment within console.log ensures the updated state is used for the next rotation.
console.log("90\n" + renderMatrixAsString(currentGridState = rotateGrid(currentGridState)));
console.log("180\n" + renderMatrixAsString(currentGridState = rotateGrid(currentGridState)));
console.log("270\n" + renderMatrixAsString(currentGridState = rotateGrid(currentGridState)));
